-- 1) Verified official sources (both subpages fetched first-hand 2026-10-29; main page = 3167).
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified) VALUES
(3171, 'https://www.durham.ac.uk/study/scholarships/international/durham-inspiring-excellence-scholarships/undergraduate/', 'Durham University — Inspiring Excellence Undergraduate Scholarship (rounds 7 Dec 2026 / 15 Mar 2027 / 1 May 2027; 60%/70% continuation)', 'www.durham.ac.uk', 'scholarship', '2026-10-29', true, true),
(3172, 'https://www.durham.ac.uk/study/scholarships/international/durham-inspiring-excellence-scholarships/postgraduate/', 'Durham University — Inspiring Excellence Postgraduate Scholarship (one-year taught MSc/MA/LLM/MDS; GBP 5,000/10,000 discount)', 'www.durham.ac.uk', 'scholarship', '2026-10-29', true, true);

-- 2) 573: description/requirements rewritten to cover both routes; three official rounds
--    stored; deadline_date moved from UCAS academic date to first scholarship round; rel 10.
UPDATE scholarships SET
description = 'Durham''s Inspiring Excellence Scholarships are the university''s flagship competitive awards for self-funded international students, and for 2027 entry they run in two versions under one scheme: an undergraduate scholarship and a postgraduate taught scholarship. Both are tuition fee discounts in two tiers - GBP 5,000 or GBP 10,000. For undergraduates the discount is paid per year of a three-year degree (up to GBP 15,000 or GBP 30,000 in total), and keeping it depends on academic progress: the GBP 5,000 tier requires passing all modules with an overall mark of at least 60% each year, and the GBP 10,000 tier at least 70%, with a step-down to GBP 5,000 for 60-69%. For postgraduates on an eligible one-year full-time taught programme (MSc, MA, LLM or MDS; MBA, MSW and the MA in Theology and Ministry are excluded) the GBP 5,000 or GBP 10,000 discount is a single one-year award. Neither version can be combined with any other scholarship, funding award or sponsorship, neither has a cash alternative, and neither can be deferred - deferring enrolment forfeits the award. Selection is based on the scholarship application responses, academic achievements and potential impact, with nationality diversity and programme balance also considered. The number of awards is limited.',
requirements = 'Be classified as an overseas fee-payer and self-funded (not in receipt of any other scholarship, funding or sponsorship), apply for an eligible programme starting in September 2027, meet or exceed that programme''s entry requirements, and submit the separate Inspiring Excellence scholarship application form by one of the three round deadlines (7 December 2026, 15 March 2027 or 1 May 2027, 23:59 GMT). Undergraduates apply for the degree through UCAS (equal consideration deadline 13 January 2027, 18:00 UK time), need a valid UCAS Personal ID for the scholarship form, must firm Durham (Insurance choice and Clearing entrants are not eligible), and must not be progressing from Durham''s International Study Centre; the BA (Hons) in Theology, Ministry and Mission and BA (Hons) in Theology and Religion are excluded. Postgraduates apply for a one-year full-time in-person taught MSc, MA, LLM or MDS (MBA, MSW and MA in Theology and Ministry excluded), need the Applicant ID issued on submitting the academic application, and Durham alumni must choose between this scholarship and the Alumni Discount. You do not need to hold an academic offer when you submit the scholarship form, and an unsuccessful or offer-less first-round application is carried into the next round automatically. Both versions require full-time in-person study; English language requirements are those of the chosen programme.',
deadline = 'Three scholarship rounds for September 2027 entry (both undergraduate and postgraduate): round 1 closes 7 December 2026 (23:59 GMT), round 2 on 15 March 2027 and the final round on 1 May 2027; decisions are emailed on 18 December 2026, 29 March 2027 and 15 May 2027. Undergraduate degree applications go through UCAS with an equal consideration deadline of 13 January 2027 (18:00 UK time).',
deadline_date = '2026-12-07', deadline_type = 'fixed',
rounds = '[{"batch": 1, "deadline": "2026-12-07", "announcement": "2026-12-18", "status": "open"}, {"batch": 2, "deadline": "2027-03-15", "announcement": "2027-03-29"}, {"batch": 3, "deadline": "2027-05-01", "announcement": "2027-05-15"}]',
application_url = 'https://www.durham.ac.uk/study/scholarships/international/durham-inspiring-excellence-scholarships/',
required_documents = '["Academic application for an eligible Durham programme (UCAS for undergraduate; Durham postgraduate applicant portal for taught postgraduate)","Inspiring Excellence scholarship application form (online)","Valid UCAS Personal ID (undergraduate) or Durham Applicant ID (postgraduate)","Academic transcripts and predicted or achieved grades","English proficiency evidence as required by the chosen programme"]',
source_reliability = 10,
last_verified_at = '2026-10-30 01:00:00+05', last_updated_at = '2026-10-30 01:00:00+05',
notes = COALESCE(notes, '') || ' BATCH 38 ENRICHMENT 2026-10-29: postgraduate route added in full. The record already listed degree level Master but its text described only the undergraduate scholarship. Both official subpages read first-hand today and linked as sources 3171 (undergraduate) and 3172 (postgraduate), alongside the main-page source 3167 from Pass 131. Postgraduate version: GBP 5,000 or GBP 10,000 one-year tuition fee discount for a one-year full-time in-person taught MSc/MA/LLM/MDS commencing September 2027 (MBA, MSW and MA in Theology and Ministry excluded; Durham alumni cannot combine with the Alumni Discount and must choose). Both versions share the three scholarship rounds (7 December 2026, 15 March 2027, 1 May 2027, 23:59 GMT; notifications 18 December 2026, 29 March 2027, 15 May 2027) now stored in rounds; deadline_date moved from the UCAS academic application date (2027-01-13) to the first scholarship round (2026-12-07), mirroring the 978 rounds convention. Undergraduate continuation thresholds verified verbatim (pass all modules; at least 60% overall for the 5k tier, at least 70% for the 10k tier, step-down to GBP 5,000 at 60-69%). Description, requirements, documents and application URL rewritten to cover both routes; the stale university_scholarships side row (generic invented name with a junk award note) was rewritten to the fetched facts in the same batch. Reliability 8 -> 10 on the full first-hand read of all three scheme pages.'
WHERE id = 573 AND is_active;

-- 3) Side row 153 rewritten (generic invented name + junk award note removed).
UPDATE university_scholarships
SET scholarship_name = 'Durham Inspiring Excellence Scholarships',
    eligibility_notes = 'For self-funded overseas-fee students starting in September 2027: an undergraduate route (via UCAS, Firm choice required) worth GBP 5,000 or GBP 10,000 per year for up to three years subject to 60%/70% continuation marks, and a one-year postgraduate taught route (MSc/MA/LLM/MDS; MBA, MSW and MA in Theology and Ministry excluded) worth GBP 5,000 or GBP 10,000. Separate scholarship form in three rounds: 7 December 2026, 15 March 2027, 1 May 2027. Cannot be combined with other funding; no cash alternative; not deferrable.',
    last_verified_at = '2026-10-30 01:00:00+05'
WHERE id = 153 AND scholarship_id = 573;

